page="""<!doctype html><meta charset="utf-8"><title>Bill first step into carrying</title><style>body{background:#182932;color:#dde8e9;font:16px system-ui;margin:24px}canvas,img{max-width:100%;background:#22343e}a{color:#afd7df}button{background:#344952;color:inherit;padding:8px;margin-right:12px}</style><h1>Bill — first step into carrying</h1><p>The turn holds his feet in place, then the first step joins the revised walk. Head, suit and case retain the held master.</p><p>Preview in the actual station. Entry and the East path are prescribed. Full weight transfer, the arrival turn and saved-game handoffs still need work.</p><button id="play">Pause</button><label>View <select id="mode"><option value="sources">Recorded movement</option><option value="native">Station captures</option></select></label><label>Height <select id="height"><option value="82">82</option><option value="148">148</option><option value="27">27</option></select></label><label> Time <input id="time" type="number" min="0" max="3.3" step="0.05" value="0" style="width:70px"></label><p id="clock"></p><canvas width="960" height="650"></canvas><p>Recorded movement uses every captured source and physical position at60Hz. Station captures are sampled native screenshots.</p><p><a href="candidate-review.png">First-step poses</a> · <a href="../bill-carry-east-gait-v2/candidate-review.png">Walking poses</a></p>SECTIONS<script>const data=DATA,canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),images={},folder='../../output/bill-carry-east-start-station-v3/';let paused=false,start=performance.now(),held=0;document.querySelector('#play').onclick=()=>{if(paused){start=performance.now()-held;paused=false}else{held=performance.now()-start;paused=true}document.querySelector('#play').textContent=paused?'Play':'Pause'};document.querySelector('#time').oninput=()=>{held=Math.min(3.3,Math.max(0,Number(document.querySelector('#time').value)))*1000;paused=true;document.querySelector('#play').textContent='Play'};async function boot(){const names=[...new Set(data.journeys.flatMap(j=>[...j.records.map(r=>r.sourceCapture),...j.captures.map(n=>n.replace('.png','-crop.png'))]))];await Promise.all(names.map(name=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[name]=im;resolve()};im.onerror=reject;im.src=folder+name})));requestAnimationFrame(draw)}function draw(now){const t=((paused?held:now-start)%3900)/1000,mode=document.querySelector('#mode').value;ctx.fillStyle='#22343e';ctx.fillRect(0,0,960,650);ctx.font='20px system-ui';data.journeys.forEach((j,i)=>{const x=i%2*480,y=Math.floor(i/2)*325,r=j.records[Math.min(Math.floor(t*60),j.records.length-1)];ctx.fillStyle='#dde8e9';ctx.fillText(`${j.candidate?'REVISED':'CURRENT'} · ${j.helmet?'helmet':'bare'}`,x+20,y+25);if(mode==='native'){let name=j.captures.filter(n=>Number(n.slice(-7,-4))/60<=t).at(-1)||j.captures[0];ctx.drawImage(images[name.replace('.png','-crop.png')],x+100,y+40,225,270)}else{ctx.strokeStyle='#455b65';for(let gx=25;gx<455;gx+=30){ctx.beginPath();ctx.moveTo(x+gx,y+245);ctx.lineTo(x+gx,y+252);ctx.stroke()}ctx.beginPath();ctx.moveTo(x+20,y+245);ctx.lineTo(x+460,y+245);ctx.stroke();const px=x+100+(r.foot[0]-j.records[0].foot[0])*Number(document.querySelector('#height').value)/(384*.17),s=Number(document.querySelector('#height').value)/148;ctx.drawImage(images[r.sourceCapture],px-128*s,y+245-224*s,256*s,256*s);ctx.fillStyle='#dde8e9';ctx.fillText(r.starting?'first step':r.turning?'turn':r.stage==='workshop_unload'?'arrival':'carrying walk',x+20,y+295)}});document.querySelector('#clock').textContent=`${Math.min(t,3.3).toFixed(2)}s — recorded path repeats after arrival`;requestAnimationFrame(draw)}boot();</script>"""
